// [S4] Authorization-negative tests — adult health data is private from the Family Head (RULE 8).
using FamilyVeda.Application.Common;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Records;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Records;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace FamilyVeda.UnitTests;

public sealed class AdultPrivacyAuthorizationTests
{
    [Fact]
    public async Task FamilyHead_ReadingAdultMembersPrivateLabReports_GetsNothingAndNoAudit()
    {
        var (db, head, adult, report) = await SeedAsync();
        var service = new RecordService(db, new StubCurrentUser(head.Id), Options.Create(new StorageOptions()));

        // Phase 2: the list is reachable but contains only reports the adult shared — none here.
        (await service.GetLabReportsAsync(adult.Id, CancellationToken.None)).Should().BeEmpty();
        await FluentActions.Awaiting(() => service.GetLabReportDetailAsync(report.Id, CancellationToken.None))
            .Should().ThrowAsync<NotFoundException>();
        await FluentActions.Awaiting(() => service.GetVitalsAsync(adult.Id, CancellationToken.None))
            .Should().ThrowAsync<NotFoundException>();
        (await db.AuditLogs.CountAsync()).Should().Be(0);
    }

    [Fact]
    public async Task AdultMember_ReadingOwnLabReport_GetsDeterministicRangeStatus()
    {
        var (db, _, adult, report) = await SeedAsync();
        var adultUserId = (await db.Members.SingleAsync(x => x.Id == adult.Id)).UserId!.Value;
        var service = new RecordService(db, new StubCurrentUser(adultUserId), Options.Create(new StorageOptions()));

        var detail = await service.GetLabReportDetailAsync(report.Id, CancellationToken.None);

        detail.Values.Should().ContainSingle(x => x.RangeStatus == LabRangeStatus.BelowRange);
    }

    private static async Task<(AppDbContext Db, UserAccount Head, Member Adult, LabReport Report)> SeedAsync()
    {
        var options = new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;
        var db = new AppDbContext(options);
        var head = new UserAccount { Email = "synthetic-head@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic Head", UserType = UserType.FamilyUser };
        var adultUser = new UserAccount { Email = "synthetic-adult@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic Adult", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Privacy Family", CreatedByUser = head };
        var headMember = new Member { Family = family, User = head, DisplayName = "Synthetic Head", DateOfBirth = new DateOnly(1970, 1, 1), Role = FamilyRole.Head };
        var adult = new Member { Family = family, User = adultUser, DisplayName = "Synthetic Adult", DateOfBirth = new DateOnly(1995, 1, 1), Role = FamilyRole.AdultMember };
        var report = new LabReport { Member = adult, OriginalFileName = "synthetic-cbc.png", StoredFileName = "synthetic-cbc.png", ContentType = "image/png", SizeBytes = 100, OcrStatus = OcrStatus.Completed };
        var value = new LabValue { LabReport = report, Analyte = "Synthetic Hb", Value = 11.2m, Unit = "g/dL", ReferenceLow = 12.0m, ReferenceHigh = 15.0m, WasManuallyConfirmed = true };
        db.AddRange(head, adultUser, family, headMember, adult, report, value);
        await db.SaveChangesAsync();
        return (db, head, adult, report);
    }

    private sealed class StubCurrentUser(Guid userId) : ICurrentUser
    {
        public bool IsAuthenticated => true;
        public Guid UserId => userId;
        public UserType UserType => UserType.FamilyUser;
    }
}
